def contains_balanced_paren(paren_string: str) -> bool:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    determine if the string contains all balanced parentheses. For a string to contain all balanced parentheses,
    the number of open parentheses must equal the number of closing parentheses. Any group of nested parentheses
    is considered a valid group and not a complete group.
    >>> contains_balanced_paren('(()())')
    True
    """
    bracket_pairs = {"(": ")", "{": "}", "[": "]"}
    stack = []
    for p in paren_string:
        if p in bracket_pairs:
            stack.append(p)
        elif p in bracket_pairs.values():
            if not stack or bracket_pairs[stack.pop()] != p:
                return False
    return len(stack) == 0


