    """ Given a string containing parentheses, calculate the depth of parentheses using a stack.
    The depth of the parentheses is equal to the length of the parentheses group.
    If the parentheses are balanced, the depth is the maximum number of opening parentheses in a group.
    The depth of unbalanced parentheses is set to -1.
    >>> parenthesis_depth('(()())')
    2
    """
    stacks = []
    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            stacks.append(paren_string[i])
        if paren_string[i] == ')':
            stacks.pop()
    return len(stacks)


