def get_factorial(n: int) -> int:
    """ Given n, return the factorial of n. The factorial of 0 is 1.
    >>> get_factorial(0)
    1
    >>> get_factorial(5)
    120
    """
    if n == 0:
        return 1
    else:
        return n * get_factorial(n - 1)


def is_prime(n: int) -> bool:
    """ A number is considered prime if it has no factors other than 1 and
    itself.

    >>> is_prime(2)
    True
    >>> is_prime(3)
    True
    >>> is_prime(4)
    False
    """
    if n == 1:
        return False
    else:
        return all(n % i != 0 for i in range(2, n)) if n > 2 else True


